tasks.answer:
scores = {
    '초록 코드': [5, 4, 4, 5],
    '잔반 제로': [4, 4, 3, 5],
    '자리 요정': [5, 5, 4, 4, 5],
}

avg = {}
for team, s in scores.items():
    avg[team] = sum(s) / len(s)

for rank, team in enumerate(sorted(avg, key=avg.get, reverse=True), 1):
    print(f"{rank}위 {team} {avg[team]:.2f}점")
